public readonly ref struct Utf8Span
{
    private readonly ReadOnlySpan<byte> s_value;

    public Utf8Span(ReadOnlySpan<byte> value) => s_value = value;

    public int Length => s_value.Length;

    public bool IsEmpty => s_value.IsEmpty;

    public ReadOnlySpan<byte> AsSpan() => s_value;

    public byte[] ToArray() => s_value.ToArray();

    public bool StartsWith(Utf8Span value) => s_value.StartsWith(value.AsSpan());

    public bool EndsWith(Utf8Span value) => s_value.EndsWith(value.AsSpan());

    // This is deliberately not a == operator because we don't want to make it easy
    // to accidentally do UTF-8 vs UTF-16 string comparisons.
    public bool StringEquals(string value)
    {
        if (s_value.Length < value.Length)
            return false;

        for (int i = 0; i < value.Length; i++)
        {
            int ch = s_value[i];
            if (ch > 0x7F)
                return Encoding.UTF8.GetString(s_value) == value;

            // We are assuming here that valid UTF8 encoded byte > 0x7F cannot map to a character with code point <= 0x7F
            if (ch != value[i])
                return false;
        }

        return s_value.Length == value.Length; // All char ANSI, all matching
    }

    public override bool Equals(object obj) => false;

    public override int GetHashCode()
    {
        HashCode h = default;
        h.AddBytes(s_value);
        return h.ToHashCode();
    }

    public override string ToString() => Encoding.UTF8.GetString(s_value);

    public static implicit operator Utf8Span(ReadOnlySpan<byte> s) => new Utf8Span(s);

    public static bool operator ==(Utf8Span left, Utf8Span right)
        => left.s_value.SequenceEqual(right.s_value);

    public static bool operator !=(Utf8Span left, Utf8Span right)
        => !left.s_value.SequenceEqual(right.s_value);
}
